            Describe.Lean(DescribeId.Create("discrete-corner-output"), DeclarationHandle.Create("D5/S3/Geometry/OriginalLabelTwoSum/HistorySeed.discreteCornerOutput"), H("discreteCornerOutput"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(SourceText("The following are literal source declarations, not elaborated metadata. Literal common source context: noncomputable section; open Set Finset; namespace D5.S3.Geometry.OriginalLabelTwoSum.HistorySeed; open OriginalLabelTwoSum HistoryCorners HistoryLeafCap; open FiniteElementaryCollapse FiniteRelativeSimplicialCollapse; variable {V : Type*} [Fintype V] [DecidableEq V]. Imports: D5.S3.Geometry.OriginalLabelTwoSum.HistoryLeafCap, D5.S3.Geometry.OriginalLabelTwoSum.Graph, D5.S3.Geometry.OriginalLabelTwoSum.Rename. \nExact public SOURCE declaration and body:\ndef discreteCornerOutput (W A B : Finset V) (hA : A ⊆ W) :\n    Output (residual W A B) (corner W A B (discrete W)) := by\n  classical\n  by_cases hA0 : A = ∅\n  · subst A\n    have he : corner W ∅ B (discrete W) = discrete (residual W ∅ B) := by\n      apply SetLike.ext; intro s\n      change (s ⊆ residual W ∅ B ∧ s ∪ ∅ ⊆ W ∧ (s ∪ ∅).card ≤ 1) ↔ _\n      simp only [Finset.union_empty]\n      exact ⟨fun h => ⟨h.1, h.2.2⟩, fun h =>\n        ⟨h.1, h.1.trans Finset.sdiff_subset, h.2⟩⟩\n    rw [he]\n    exact discreteOutput _\n  · by_cases hcard : A.card ≤ 1\n    · have hAn : A.Nonempty := Finset.nonempty_iff_ne_empty.mpr hA0\n      let a := hAn.choose\n      have ha : a ∈ A := hAn.choose_spec\n      exact .unit (by\n        apply SetLike.ext; intro s\n        constructor\n        · rintro ⟨hs, hW, hc⟩\n          have hs0 : s = ∅ := by\n            apply Finset.eq_empty_iff_forall_notMem.mpr\n            intro v hv\n            rcases small_face (s ∪ A) hc with he | ⟨q, he⟩\n            · have hmem : a ∈ s ∪ A := Finset.mem_union_right _ ha\n              rw [he] at hmem\n              exact (Finset.notMem_empty _ hmem)\n            · have haq : a = q := Finset.mem_singleton.mp (he ▸ Finset.mem_union_right s ha)\n              have hvq : v = q := Finset.mem_singleton.mp (he ▸ Finset.mem_union_left A hv)\n              have hvA : v ∈ A := (hvq.trans haq.symm).symm ▸ ha\n              exact (Finset.mem_sdiff.mp (hs hv)).2 (Finset.mem_union_left _ hvA)\n          simp [hs0]\n        · intro hs\n          have he : s = ∅ := Finset.subset_empty.mp hs\n          subst s\n          exact ⟨Finset.empty_subset _, by simpa using hA, by simpa using hcard⟩)\n    · exact .void (by\n        apply SetLike.ext; intro s\n        constructor\n        · rintro ⟨hs, hW, hc⟩\n          exact False.elim (hcard ((Finset.card_le_card Finset.subset_union_right).trans hc))\n        · intro h; exact False.elim h)")), DescribeRole.Definition),
